package ru.folio.notes;

import android.graphics.*;
import android.view.*;
import android.widget.*;

final class Eyedropper extends View {
    final MainActivity a;final NotesView source;final Ink.Page page;final MainActivity.ColorResult accept;final Runnable done;
    final Bitmap lens=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);final Canvas lensCanvas=new Canvas(lens);final Paint p=new Paint(3);final Path circle=new Path();final RectF destination=new RectF();
    float x=-1,y;int selected,pointer=-1;boolean closed;FrameLayout overlay;TextView caption;
    Eyedropper(MainActivity a,int color,MainActivity.ColorResult accept,Runnable done){super(a);this.a=a;source=a.canvas;page=source.page;this.accept=accept;this.done=done;selected=color;setContentDescription("Пипетка: ведите по холсту. Цвет применяется сразу; отпустите, чтобы закончить");}
    static Eyedropper show(MainActivity a,int color,MainActivity.ColorResult accept){return show(a,color,accept,null);}
    static Eyedropper show(MainActivity a,int color,MainActivity.ColorResult accept,Runnable done){if(a.canvas==null||a.body==null)return null;if(a.eyedropper!=null)a.eyedropper.close();a.canvas.finishGesture(false);a.canvas.closePalette();Eyedropper view=new Eyedropper(a,color,accept,done);a.eyedropper=view;view.overlay=new FrameLayout(a);view.overlay.addView(view,new FrameLayout.LayoutParams(-1,-1));LinearLayout actions=a.row();actions.setBackground(Studio.surface(Studio.SURFACE,20,a.getResources().getDisplayMetrics().density));a.pad(actions,12,6);view.caption=a.text("Коснитесь цвета на холсте",12,Studio.TEXT,true);actions.addView(view.caption);a.space(actions,12);actions.addView(Studio.button(a,"Закрыть",false,view::close));FrameLayout.LayoutParams pos=new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);pos.bottomMargin=a.dp(70);view.overlay.addView(actions,pos);a.body.addView(view.overlay,new FrameLayout.LayoutParams(-1,-1));return view;}
    void close(){if(closed)return;closed=true;if(a.eyedropper==this)a.eyedropper=null;if(overlay!=null&&overlay.getParent() instanceof ViewGroup)((ViewGroup)overlay.getParent()).removeView(overlay);if(done!=null)done.run();}
    void sample(float sx,float sy){if(closed||a.canvas!=source||source.page!=page){close();return;}NotesView v=source;x=sx;y=sy;float wx=v.px(sx),wy=v.py(sy),span=24/v.scale();Canvas c=lensCanvas;c.drawColor(page.paper);c.save();c.scale(96/span,96/span);c.translate(-wx+span/2,-wy+span/2);InkRenderer.region(c,page,v.background,v.spatial.query(wx-span,wy-span,wx+span,wy+span),java.util.Collections.emptySet(),wx-span,wy-span,wx+span,wy+span,v.scale());c.restore();int color=lens.getPixel(48,48)|0xff000000;if(color!=selected){selected=color;accept.accept(color);}if(caption!=null)caption.setText(ColorModel.hex(selected)+"  ·  Отпустите для завершения");invalidate();}
    public boolean onTouchEvent(MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN)pointer=e.getPointerId(0);if(action==MotionEvent.ACTION_CANCEL){close();return true;}int i=e.findPointerIndex(pointer);if(i>=0&&(action==MotionEvent.ACTION_DOWN||action==MotionEvent.ACTION_MOVE||action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_POINTER_UP&&e.getPointerId(e.getActionIndex())==pointer)){sample(e.getX(i),e.getY(i));if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_POINTER_UP){performClick();close();}}return true;}
    public boolean performClick(){super.performClick();return true;}
    protected void onDraw(Canvas c){if(x<0||closed)return;float r=a.dp(42),cx=Ink.clamp(x,r+a.dp(8),getWidth()-r-a.dp(8)),cy=Ink.clamp(y-a.dp(78),r+a.dp(8),getHeight()-r-a.dp(8));c.save();circle.rewind();circle.addCircle(cx,cy,r,Path.Direction.CW);c.clipPath(circle);destination.set(cx-r,cy-r,cx+r,cy+r);c.drawBitmap(lens,null,destination,p);c.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(5));p.setColor(selected);c.drawCircle(cx,cy,r,p);p.setColor(Studio.TEXT);p.setStrokeWidth(a.dp(1));c.drawCircle(cx,cy,r+a.dp(3),p);c.drawCircle(cx,cy,a.dp(3),p);c.drawLine(cx-a.dp(8),cy,cx+a.dp(8),cy,p);c.drawLine(cx,cy-a.dp(8),cx,cy+a.dp(8),p);p.setStyle(Paint.Style.FILL);}
    protected void onDetachedFromWindow(){closed=true;if(a.eyedropper==this)a.eyedropper=null;lens.recycle();super.onDetachedFromWindow();}
}
